-- Artifact-derived OMR v2.0.11 PostgreSQL schema at Alembic revision
-- 3f8d7acdf7f9, generated by actually running the Python Quay codebase's
-- own `alembic upgrade 3f8d7acdf7f9` against a real, empty PostgreSQL 16
-- server -- the same command CI's `make go-schema` uses for the SQLite
-- target schema, just pointed at Postgres instead of SQLite. This is a
-- genuine schema derivation (not the hand-built approximation used in the
-- initial POC's postgres_copy_integration_test.go), replacing that gap for
-- the tables it covers.
--
-- schema-only pg_dump output (`--schema-only --no-owner --no-privileges`);
-- the `\restrict`/`\unrestrict` psql pragma lines pg_dump 16.14 adds were
-- stripped since they are not portable SQL.
--
-- Reproduction:
--   1. podman run -d --name pg-omr-schema -e POSTGRES_USER=quay \
--        -e POSTGRES_PASSWORD=quay -e POSTGRES_DB=quay -p 5436:5432 \
--        docker.io/library/postgres:16
--   2. psql -U quay -d quay -c 'CREATE EXTENSION IF NOT EXISTS pg_trgm;'
--   3. In a python:3.12 container with this repo mounted at /src:
--        apt-get install -y libgpgme-dev libldap2-dev libsasl2-dev swig gcc libpq-dev
--        pip install -r requirements.txt
--        mkdir -p /tmp/quayconf/stack && cat > /tmp/quayconf/stack/config.yaml <<EOF
--        DB_URI: postgresql://quay:quay@localhost:5436/quay
--        SETUP_COMPLETE: true
--        DATABASE_SECRET_KEY: schema-extraction-only
--        SECRET_KEY: schema-extraction-only
--        EOF
--        cd /src && QUAYCONF=/tmp/quayconf/ PYTHONPATH=. alembic upgrade 3f8d7acdf7f9
--   4. pg_dump -U quay -d quay --schema-only --no-owner --no-privileges
--
-- Versions used: PostgreSQL 16.14 (docker.io/library/postgres:16), Python
-- 3.12.13, alembic 1.13.1 (this repo's requirements.txt pin), this repo's
-- data/migrations/versions/ at the commit that added this file (the
-- migration chain from base to 3f8d7acdf7f9 is immutable Alembic history,
-- so this reproduces regardless of later migrations added after it).
--
-- Verified against the existing artifact-derived SQLite fixture
-- (internal/dal/dbcore/testdata/omr_v2.0.11_3f8d7acdf7f9.sql): identical
-- table-name set (97/97), and this POC's four representative tables
-- (accesstoken-adjacent "user", repository, manifest, tag) matched the
-- SQLite fixture's column names/types/order exactly.
--
-- IMPORTANT FINDING: mediatype and imagestoragelocation row IDs are NOT
-- stable across installations. `image/docker/schema1.py`,
-- `image/docker/schema2.py`, and `image/oci/__init__.py` define their
-- content-type lists as Python `set`s, and three migrations
-- (9093adccc784, c00a1f15968b, 04b9d2191450) insert mediatype rows by
-- iterating those sets -- so the specific integer ID assigned to each of
-- mediatype ids 13-18 depends on that installation's Python hash seed at
-- migration time (confirmed by rerunning this exact migration chain twice
-- with different PYTHONHASHSEED values and observing different id<->name
-- assignments for ids 15/16 and 17/18). imagestoragelocation similarly
-- gets an extra, config-dependent "default" row from application runtime
-- code, not from Alembic. A production copier must copy these lookup
-- tables' actual rows from each source instance rather than assuming a
-- fixed universal ID mapping from a baseline.
--
-- PostgreSQL database dump
--


-- Dumped from database version 16.14 (Debian 16.14-1.pgdg13+1)
-- Dumped by pg_dump version 16.14 (Debian 16.14-1.pgdg13+1)

SET statement_timeout = 0;
SET lock_timeout = 0;
SET idle_in_transaction_session_timeout = 0;
SET client_encoding = 'UTF8';
SET standard_conforming_strings = on;
SELECT pg_catalog.set_config('search_path', '', false);
SET check_function_bodies = false;
SET xmloption = content;
SET client_min_messages = warning;
SET row_security = off;

--
-- Name: pg_trgm; Type: EXTENSION; Schema: -; Owner: -
--

CREATE EXTENSION IF NOT EXISTS pg_trgm WITH SCHEMA public;


--
-- Name: EXTENSION pg_trgm; Type: COMMENT; Schema: -; Owner: -
--

COMMENT ON EXTENSION pg_trgm IS 'text similarity measurement and index searching based on trigrams';


SET default_tablespace = '';

SET default_table_access_method = heap;

